export const WINGS_D3 = {}, DETAILS_D3 = {};
for (const [id, r] of Object.entries(ROOMS)) {
  const { list, ...topic } = r;
  topic.items = list.map(([ja, en, pic, fact, , , , year]) => [ja, en, pic, fact, null, year]);
  WINGS_D3[id] = topic;
  DETAILS_D3[id] = Object.fromEntries(list.map(([, en, , , about, sEn, sJa]) => [en, [about, `${sEn} / ${sJa}`]]));
}
